-- ===================================================================================
-- Speak Up Speech Therapy Center - Complete SQL Server Database Script
-- شامل كافة البيانات الفعلية كاملة من Google Sheets (219 عميل، 1,134 جلسة، 200 سند قبض، 75 مشتريات)
-- ===================================================================================

IF NOT EXISTS (SELECT * FROM sys.databases WHERE name = 'SpeakUpDB')
BEGIN
    CREATE DATABASE SpeakUpDB COLLATE Arabic_100_CI_AS;
END
GO

USE SpeakUpDB;
GO

-- حذف الجداول السابقة لإعادة البناء الشامل
IF OBJECT_ID('dbo.purchases', 'U') IS NOT NULL DROP TABLE dbo.purchases;
IF OBJECT_ID('dbo.payments', 'U') IS NOT NULL DROP TABLE dbo.payments;
IF OBJECT_ID('dbo.sessions', 'U') IS NOT NULL DROP TABLE dbo.sessions;
IF OBJECT_ID('dbo.weekly_schedule', 'U') IS NOT NULL DROP TABLE dbo.weekly_schedule;
IF OBJECT_ID('dbo.clients', 'U') IS NOT NULL DROP TABLE dbo.clients;
IF OBJECT_ID('dbo.staff', 'U') IS NOT NULL DROP TABLE dbo.staff;
IF OBJECT_ID('dbo.branches', 'U') IS NOT NULL DROP TABLE dbo.branches;
GO

-- 1. جدول الفروع
CREATE TABLE dbo.branches (
    branch_id NVARCHAR(20) PRIMARY KEY,
    branch_name NVARCHAR(100) NOT NULL,
    address NVARCHAR(255),
    session_price DECIMAL(10,2) NOT NULL DEFAULT 150.00,
    assessment_price DECIMAL(10,2) NOT NULL DEFAULT 250.00,
    status NVARCHAR(20) DEFAULT N'Active'
);
GO

-- 2. جدول الموظفين وفريق العمل
CREATE TABLE dbo.staff (
    staff_id NVARCHAR(50) PRIMARY KEY,
    name NVARCHAR(150) NOT NULL,
    phone NVARCHAR(30),
    email NVARCHAR(100),
    department NVARCHAR(50) DEFAULT N'Therapist',
    specialty NVARCHAR(100) DEFAULT N'Speech Therapist',
    status NVARCHAR(20) DEFAULT N'Active'
);
GO

-- 3. جدول الأطفال والعملاء (مع كامل الأعمدة الجديدة: Start_Date, End_Date, Photo_URL)
CREATE TABLE dbo.clients (
    client_id NVARCHAR(50) PRIMARY KEY,
    name NVARCHAR(150) NOT NULL,
    phone NVARCHAR(30),
    branch_id NVARCHAR(20) FOREIGN KEY REFERENCES dbo.branches(branch_id),
    dob DATE,
    address NVARCHAR(255),
    diagnosis NVARCHAR(150),
    status NVARCHAR(30) DEFAULT N'Active',
    start_date DATE,
    end_date DATE,
    photo_url NVARCHAR(255),
    created_at DATETIME DEFAULT GETDATE()
);
GO

-- 4. جدول المواعيد الأسبوعية الثابتة
CREATE TABLE dbo.weekly_schedule (
    schedule_id NVARCHAR(50) PRIMARY KEY,
    client_id NVARCHAR(50) NOT NULL FOREIGN KEY REFERENCES dbo.clients(client_id) ON DELETE CASCADE,
    branch_id NVARCHAR(20) FOREIGN KEY REFERENCES dbo.branches(branch_id),
    day_of_week NVARCHAR(20) NOT NULL,
    session_time NVARCHAR(20) NOT NULL,
    staff_id NVARCHAR(50) FOREIGN KEY REFERENCES dbo.staff(staff_id),
    session_type NVARCHAR(50) DEFAULT N'S.T Session',
    fee DECIMAL(10,2) NOT NULL DEFAULT 150.00,
    net_fee DECIMAL(10,2) NOT NULL DEFAULT 150.00,
    generate_from DATE,
    generate_until DATE
);
GO

-- 5. جدول سجل الجلسات اليومية الفعلية
CREATE TABLE dbo.sessions (
    session_id NVARCHAR(50) PRIMARY KEY,
    client_id NVARCHAR(50) NOT NULL FOREIGN KEY REFERENCES dbo.clients(client_id),
    staff_id NVARCHAR(50) FOREIGN KEY REFERENCES dbo.staff(staff_id),
    session_date DATE NOT NULL,
    session_time NVARCHAR(20) NOT NULL,
    session_type NVARCHAR(50) NOT NULL DEFAULT N'S.T Session',
    session_status NVARCHAR(20) NOT NULL DEFAULT N'SCHEDULED',
    fee DECIMAL(10,2) NOT NULL DEFAULT 150.00,
    net_fee DECIMAL(10,2) NOT NULL DEFAULT 150.00,
    notes NVARCHAR(MAX)
);
GO

-- 6. جدول سندات القبض والمدفوعات
CREATE TABLE dbo.payments (
    payment_id NVARCHAR(50) PRIMARY KEY,
    client_id NVARCHAR(50) NOT NULL FOREIGN KEY REFERENCES dbo.clients(client_id),
    branch_id NVARCHAR(20) FOREIGN KEY REFERENCES dbo.branches(branch_id),
    payment_date DATE NOT NULL,
    amount DECIMAL(10,2) NOT NULL,
    month NVARCHAR(20),
    notes NVARCHAR(MAX)
);
GO

-- 7. جدول المشتريات والمصروفات
CREATE TABLE dbo.purchases (
    purchase_id NVARCHAR(50) PRIMARY KEY,
    purchase_number NVARCHAR(20),
    purchase_date DATE NOT NULL,
    item_name NVARCHAR(200) NOT NULL,
    category NVARCHAR(100),
    supplier NVARCHAR(150),
    branch_id NVARCHAR(20) FOREIGN KEY REFERENCES dbo.branches(branch_id),
    quantity DECIMAL(10,2) DEFAULT 1,
    unit_price DECIMAL(10,2) DEFAULT 0,
    total_cost AS (quantity * unit_price),
    purchased_by NVARCHAR(100)
);
GO

