-- ===================================================================================
-- عرض نتائج الإدخال النهائي في SSMS مباشرة
-- ===================================================================================
PRINT N'=========================================================================';
PRINT N'✅ تم إنشاء قاعدة البيانات SpeakUpDB وإدراج كافة البيانات الشاملة بنجاح!';
PRINT N'   - إجمالي الفروع: ' + CAST((SELECT COUNT(*) FROM dbo.branches) AS NVARCHAR(10));
PRINT N'   - إجمالي الأخصائيين: ' + CAST((SELECT COUNT(*) FROM dbo.staff) AS NVARCHAR(10));
PRINT N'   - إجمالي الأطفال والعملاء: ' + CAST((SELECT COUNT(*) FROM dbo.clients) AS NVARCHAR(10));
PRINT N'   - إجمالي المواعيد الأسبوعية: ' + CAST((SELECT COUNT(*) FROM dbo.weekly_schedule) AS NVARCHAR(10));
PRINT N'   - إجمالي الجلسات اليومية: ' + CAST((SELECT COUNT(*) FROM dbo.sessions) AS NVARCHAR(10));
PRINT N'   - إجمالي سندات القبض: ' + CAST((SELECT COUNT(*) FROM dbo.payments) AS NVARCHAR(10));
PRINT N'   - إجمالي المشتريات: ' + CAST((SELECT COUNT(*) FROM dbo.purchases) AS NVARCHAR(10));
PRINT N'=========================================================================';

-- استعراض فوري لأول 50 عميل في جدول النتائج
SELECT TOP 50 
    client_id AS [كود الطفل],
    name AS [اسم الطفل العميل],
    phone AS [رقم الهاتف],
    branch_id AS [الفرع],
    diagnosis AS [التشخيص],
    status AS [الحالة],
    start_date AS [تاريخ البدء],
    end_date AS [تاريخ الانتهاء],
    photo_url AS [الصورة]
FROM dbo.clients
ORDER BY client_id;

-- استعراض فوري لسجل الجلسات
SELECT TOP 50 
    session_id AS [كود الجلسة],
    client_id AS [كود العميل],
    session_date AS [التاريخ],
    session_time AS [الوقت],
    session_status AS [الحالة],
    net_fee AS [الصافي]
FROM dbo.sessions
ORDER BY session_date DESC;
GO
